local MillstoneBalancerMaker = {}
local PRODUCTS = {
    iron_millstonebalancer = { name = "Železni uravnavalec mlinskih kamnov", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni uravnavalec mlinskih kamnov za mlinarje." },
    bronze_millstonebalancer = { name = "Bronast uravnavalec mlinskih kamnov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast uravnavalec mlinskih kamnov za mlinarje." },
    silver_millstonebalancer = { name = "Srebrn uravnavalec mlinskih kamnov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn uravnavalec mlinskih kamnov za mlinarje." },
    gilded_millstonebalancer = { name = "Pozlačen uravnavalec mlinskih kamnov", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen uravnavalec mlinskih kamnov za mlinarje." },
    jewel_set_millstonebalancer = { name = "Draguljast uravnavalec mlinskih kamnov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast uravnavalec mlinskih kamnov za mlinarje." },
    royal_sovereign_millstonebalancer = { name = "Kraljevski suveren uravnavalec mlinskih kamnov", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren uravnavalec mlinskih kamnov z biseri za krono." },
}
local BUILDINGS = {
    millstonebalancer_workshop = { name = "Millstonebalancer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millstonebalancer_house = { name = "Millstonebalancer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millstonebalancer_atelier = { name = "Mojstrski millstonebalancer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millstonebalancer_palace = { name = "Suverena millstonebalancer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillstoneBalancerMaker.ironStock=18; MillstoneBalancerMaker.bronzeStock=14; MillstoneBalancerMaker.woodStock=10; MillstoneBalancerMaker.leatherStock=8; MillstoneBalancerMaker.silverStock=8; MillstoneBalancerMaker.goldStock=6; MillstoneBalancerMaker.jewelStock=4; MillstoneBalancerMaker.pearlStock=4
MillstoneBalancerMaker.productStock = {}; MillstoneBalancerMaker.buildings = {}; MillstoneBalancerMaker.maker = nil; MillstoneBalancerMaker.activeMaking = {}; MillstoneBalancerMaker.totalProducts = 0; MillstoneBalancerMaker.dayTimer = 0
function MillstoneBalancerMaker.init() MillstoneBalancerMaker.ironStock=18; MillstoneBalancerMaker.bronzeStock=14; MillstoneBalancerMaker.woodStock=10; MillstoneBalancerMaker.leatherStock=8; MillstoneBalancerMaker.silverStock=8; MillstoneBalancerMaker.goldStock=6; MillstoneBalancerMaker.jewelStock=4; MillstoneBalancerMaker.pearlStock=4; MillstoneBalancerMaker.productStock={}; MillstoneBalancerMaker.buildings={}; MillstoneBalancerMaker.maker=nil; MillstoneBalancerMaker.activeMaking={}; MillstoneBalancerMaker.totalProducts=0; MillstoneBalancerMaker.dayTimer=0; print("[MillstoneBalancerMaker] Royal Millstone Balancer Maker System initialized (6 products, 4 buildings)") end
function MillstoneBalancerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneBalancerMaker.maker={name=n or ("Uravnalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Uravnalec najet: %s (spretnost: %d)",MillstoneBalancerMaker.maker.name,s),"success") end; return true end
function MillstoneBalancerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneBalancerMaker.build(id) local ok,e=MillstoneBalancerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneBalancerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneBalancerMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneBalancerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneBalancerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneBalancerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneBalancerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneBalancerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneBalancerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneBalancerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneBalancerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneBalancerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneBalancerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneBalancerMaker.buildings==0 then return false,"Potrebna uravnavalna delavnica" end; if not MillstoneBalancerMaker.maker then return false,"Potreben uravnalec" end; return true end
function MillstoneBalancerMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneBalancerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneBalancerMaker.ironStock=MillstoneBalancerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneBalancerMaker.bronzeStock=MillstoneBalancerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneBalancerMaker.woodStock=MillstoneBalancerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneBalancerMaker.leatherStock=MillstoneBalancerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneBalancerMaker.silverStock=MillstoneBalancerMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneBalancerMaker.goldStock=MillstoneBalancerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneBalancerMaker.jewelStock=MillstoneBalancerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneBalancerMaker.pearlStock=MillstoneBalancerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneBalancerMaker.maker then t=math.max(1,t-math.floor(MillstoneBalancerMaker.maker.skill/13)) end; table.insert(MillstoneBalancerMaker.activeMaking,{id="millstonebalancer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneBalancerMaker.completeMaking(m) local q=1.0+(MillstoneBalancerMaker.getQualityBonus()/100); if MillstoneBalancerMaker.maker then q=q+(MillstoneBalancerMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneBalancerMaker.productStock[m.productType]=(MillstoneBalancerMaker.productStock[m.productType] or 0)+m.quantity; MillstoneBalancerMaker.totalProducts=MillstoneBalancerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneBalancerMaker.maker then MillstoneBalancerMaker.maker.itemsMade=MillstoneBalancerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneBalancerMaker.maker.skill=math.min(100,MillstoneBalancerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Uravnalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonebalancer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneBalancerMaker.update(dt) if not _G.state then return end; MillstoneBalancerMaker.dayTimer=MillstoneBalancerMaker.dayTimer+dt; if MillstoneBalancerMaker.dayTimer>=30 then MillstoneBalancerMaker.dayTimer=0; for i=#MillstoneBalancerMaker.activeMaking,1,-1 do local m=MillstoneBalancerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneBalancerMaker.completeMaking(m); table.remove(MillstoneBalancerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneBalancerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneBalancerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneBalancerMaker.getStats() return {ironStock=MillstoneBalancerMaker.ironStock,bronzeStock=MillstoneBalancerMaker.bronzeStock,woodStock=MillstoneBalancerMaker.woodStock,leatherStock=MillstoneBalancerMaker.leatherStock,silverStock=MillstoneBalancerMaker.silverStock,goldStock=MillstoneBalancerMaker.goldStock,jewelStock=MillstoneBalancerMaker.jewelStock,pearlStock=MillstoneBalancerMaker.pearlStock,productStock=MillstoneBalancerMaker.productStock,numBuildings=#MillstoneBalancerMaker.buildings,hasMaker=MillstoneBalancerMaker.maker~=nil,makerName=MillstoneBalancerMaker.maker and MillstoneBalancerMaker.maker.name or "—",makerSkill=MillstoneBalancerMaker.maker and MillstoneBalancerMaker.maker.skill or 0,activeMaking=#MillstoneBalancerMaker.activeMaking,totalProducts=MillstoneBalancerMaker.totalProducts} end
return MillstoneBalancerMaker
